// The C shim between the generic Swift shell and a LeanNative app compiled to C (native mode).
// Generic: the app is reached only through `leannative_app_initialize` (generated by framework/native/scripts/
// ios_lean_sources.sh: it calls the app's root module initializer) and the `leannative_lean_*`
// functions exported by LeanNative.Native.
#include <lean/lean.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "leannative.h"

lean_object *leannative_app_initialize(void);
lean_object *leannative_lean_start(lean_object *);
lean_object *leannative_lean_event(lean_object *);
lean_object *leannative_lean_drain(lean_object *);
lean_object *leannative_lean_system(lean_object *);
lean_object *leannative_lean_cap_result(lean_object *);
lean_object *leannative_lean_wait(lean_object *);
// in libleanrt but not in lean.h: registers a thread Lean did not create
void lean_initialize_thread(void);
void lean_initialize_runtime_module(void);

// Modules that import anything under `Lean` (LeanNative.Json uses Lean.Data.Json) call `lean_initialize()`
// before their own initializers. The toolchain's version starts the whole compiler (kernel, elaborator,
// dynamic loading), none of which an app uses and none of which is linked; the runtime is enough.
void lean_initialize(void) { lean_initialize_runtime_module(); }

// The stack of every thread Lean creates (8 MB is a macOS main thread's; Lean's deepest app code, key
// derivation and JSON, runs in well under that). The runtime exports the setter but no header declares it.
#define LEANNATIVE_THREAD_STACK ((size_t)16 << 20)
extern void lean_internal_set_thread_stack_size(size_t size);

int leannative_boot(void) {
    lean_object *res = leannative_app_initialize();
    lean_io_mark_end_initialization();
    if (!lean_io_result_is_ok(res)) {
        lean_io_result_show_error(res);
        lean_dec_ref(res);
        return 1;
    }
    lean_dec_ref(res);
    // Lean's default thread stack is sized for the compiler (hundreds of MB): on iOS a dozen threads use up
    // the app's address space and the next one cannot start. Every thread Lean creates from here on, the
    // task manager's workers and each dedicated task, gets LEANNATIVE_THREAD_STACK instead.
    lean_internal_set_thread_stack_size(LEANNATIVE_THREAD_STACK);
    lean_init_task_manager();
    return 0;
}

// A thread Lean did not create must be registered before it calls into Lean.
static pthread_key_t registered_key;
static pthread_once_t registered_once = PTHREAD_ONCE_INIT;
static void make_key(void) { pthread_key_create(&registered_key, NULL); }
static void enter_lean(void) {
    pthread_once(&registered_once, make_key);
    if (pthread_getspecific(registered_key) == NULL) {
        lean_initialize_thread();
        pthread_setspecific(registered_key, (void *)1);
    }
}

static char *take_string(lean_object *res) {
    if (!lean_io_result_is_ok(res)) {
        lean_io_result_show_error(res);
        lean_dec_ref(res);
        return strdup("{\"error\":\"lean-io\"}");
    }
    lean_object *s = lean_io_result_get_value(res);
    char *out = strdup(lean_string_cstr(s));
    lean_dec_ref(res);
    return out;
}

static void drop(lean_object *res) {
    if (!lean_io_result_is_ok(res)) lean_io_result_show_error(res);
    lean_dec_ref(res);
}

char *leannative_start(void) { enter_lean(); return take_string(leannative_lean_start(lean_box(0))); }
char *leannative_event(const char *json) { enter_lean(); return take_string(leannative_lean_event(lean_mk_string(json))); }
char *leannative_system(const char *json) { enter_lean(); return take_string(leannative_lean_system(lean_mk_string(json))); }
char *leannative_drain(void) { enter_lean(); return take_string(leannative_lean_drain(lean_box(0))); }
void leannative_cap_result(const char *json) { enter_lean(); drop(leannative_lean_cap_result(lean_mk_string(json))); }
void leannative_wait(void) { enter_lean(); drop(leannative_lean_wait(lean_box(0))); }
